
from pathlib import Path
import json

import joblib
import numpy as np
import pandas as pd
from sklearn.ensemble import IsolationForest
from sklearn.impute import SimpleImputer
from sklearn.pipeline import Pipeline
from sklearn.preprocessing import StandardScaler

ROOT = Path(__file__).resolve().parents[1]
DATA_DIR = ROOT / "data"
OUTPUT_DIR = ROOT / "outputs"
MODEL_DIR = OUTPUT_DIR / "models"
ANOMALY_DIR = OUTPUT_DIR / "anomaly"

MODEL_DIR.mkdir(parents=True, exist_ok=True)
ANOMALY_DIR.mkdir(parents=True, exist_ok=True)

# Locate the training split generated by 02_prepare_data.py.
# If filenames differ, the script will print the CSV files it finds.

candidate_files = [
    ROOT / "outputs" / "splits" / "train.csv",
]


train_path = next((p for p in candidate_files if p.is_file()), None)

if train_path is None:
    csv_files = sorted(DATA_DIR.rglob("*.csv")) if DATA_DIR.exists() else []
    print("Could not locate X_train.csv automatically.")
    print("CSV files found under data/:")
    for path in csv_files:
        print(" -", path.relative_to(ROOT))
    print(
        "\nOpen src/02_prepare_data.py and check where X_train is saved. "
        "Then update candidate_files in this script to that exact path."
    )
    raise SystemExit(1)

X_train = pd.read_csv(train_path)

# The training split should contain only the 26 numerical features.
if "label" in X_train.columns:
    X_train = X_train.drop(columns=["label"])

metadata_path = MODEL_DIR / "model_metadata.joblib"
if not metadata_path.exists():
    raise FileNotFoundError(
        f"Missing {metadata_path}. Run the preparation/training workflow first."
    )

metadata = joblib.load(metadata_path)
features = list(metadata["features"])

missing = [c for c in features if c not in X_train.columns]
if missing:
    raise ValueError(
        "Training CSV is missing required features: " + ", ".join(missing)
    )

X_train = X_train[features].apply(pd.to_numeric, errors="coerce")
X_train = X_train.replace([np.inf, -np.inf], np.nan)

# Remove rows with no usable features; median imputation handles remaining gaps.
X_train = X_train.dropna(how="all")

if len(X_train) < 10:
    raise ValueError("Not enough usable training rows for anomaly detection.")

pipeline = Pipeline([
    ("imputer", SimpleImputer(strategy="median")),
    ("scaler", StandardScaler()),
    ("detector", IsolationForest(
        n_estimators=300,
        contamination="auto",
        random_state=42,
        n_jobs=-1,
    )),
])

pipeline.fit(X_train)

model_path = MODEL_DIR / "isolation_forest.joblib"
joblib.dump(pipeline, model_path)

# Save training-score reference information for the app.
train_scores = pipeline.decision_function(X_train)
train_predictions = pipeline.predict(X_train)

metadata_out = {
    "features": features,
    "training_rows": int(len(X_train)),
    "training_source": str(train_path.relative_to(ROOT)),
    "score_definition": (
        "Isolation Forest decision_function; lower scores are more anomalous."
    ),
    "contamination": "auto",
    "random_state": 42,
    "training_flagged_fraction": float(np.mean(train_predictions == -1)),
    "training_score_quantiles": {
        "q01": float(np.quantile(train_scores, 0.01)),
        "q05": float(np.quantile(train_scores, 0.05)),
        "q50": float(np.quantile(train_scores, 0.50)),
        "q95": float(np.quantile(train_scores, 0.95)),
    },
}

with open(ANOMALY_DIR / "metadata.json", "w", encoding="utf-8") as f:
    json.dump(metadata_out, f, indent=2)

print("Anomaly detector trained successfully.")
print(f"Training file: {train_path.relative_to(ROOT)}")
print(f"Training rows: {len(X_train):,}")
print(f"Features: {len(features)}")
print(f"Model saved: {model_path}")
print(f"Metadata saved: {ANOMALY_DIR / 'metadata.json'}")
print(
    "Training rows flagged as anomalies: "
    f"{metadata_out['training_flagged_fraction'] * 100:.2f}%"
)
print("Lower decision_function scores indicate more anomalous samples.")
